// Master Hub Logic for DP 103 (temp_current)
let dps = (msg.payload && msg.payload.DP_data) ? msg.payload.DP_data.dps : msg.payload.dps;

if (dps && dps['103'] !== undefined) {
    let ambientTemp = dps['103'];

    // Engineering Validation: Ignore values that are clearly errors
    if (ambientTemp > 0 && ambientTemp < 100) { 
        msg.payload = ambientTemp;
        msg.topic = "Breaker_Ambient_Temp";
        return msg;
    }
}
return null;

let state = flow.get("ac_dash_state") || { 
    power: "OFFLINE", 
    setTemp: "--", 
    roomTemp: "--", 
    humidity: "--", 
    outTemp: "--" 
};

if (msg.topic === "nbric/ac/status") {
    if (msg.payload && msg.payload.power) state.power = msg.payload.power;
    if (msg.payload && msg.payload.temp) state.setTemp = msg.payload.temp;
} else if (msg.topic === "Temperature") {
    state.roomTemp = msg.payload;
} else if (msg.topic === "Humidity") {
    state.humidity = msg.payload;
} else if (msg.topic === "Breaker_Ambient_Temp") {
    state.outTemp = msg.payload;
}

flow.set("ac_dash_state", state);
return { payload: state };

// This version handles different Tuya node data structures
let dps = msg.payload.dps || (msg.payload.data ? msg.payload.data.dps : null);

if (dps) {
    let tempRaw = dps['101'];
    let humRaw = dps['102'];

    let messages = [null, null];

    if (tempRaw !== undefined) {
        messages[0] = { payload: tempRaw / 10, topic: "Temperature" };
    }

    if (humRaw !== undefined) {
        messages[1] = { payload: humRaw, topic: "Humidity" };
    }

    return messages;
}

return null;

let schedules = flow.get('ac_sched') || [];
let now = new Date();
let currentTime = now.getHours().toString().padStart(2, '0') + ':' + now.getMinutes().toString().padStart(2, '0');
let currentDay = now.getDay().toString();

let fireAction = null;
schedules.forEach(sched => {
    if (sched.timeStr === currentTime && (sched.day === "All" || sched.day === currentDay)) {
        fireAction = sched.action;
    }
});

if (fireAction !== null) {
    return { payload: fireAction };
}
return null;

let p = msg.payload;
// Check if the trigger is from the 2-second Injector (number timestamp) or Tuya (object)
let isTick = (typeof p === 'number'); 
let dps = (p && typeof p === 'object') ? (p.data && p.data.dps ? p.data.dps : p.dps) : null;

let isOnline = flow.get("arec_health") || false;

// Only update connection health if we received an actual hardware packet
if (!isTick && typeof p === 'string') {
    if (p === "CONNECTED" || (p.event && p.event === "CONNECTED")) isOnline = true;
    else if (p === "DISCONNECTED" || p === "ERROR" || (p.event && (p.event === "DISCONNECTED" || p.event === "ERROR"))) isOnline = false;
} else if (dps) {
    isOnline = true;
}
flow.set("arec_health", isOnline);

let lastV = parseFloat(flow.get("arec_last_v")) || 0;
let lastC = parseFloat(flow.get("arec_last_c")) || 0;
let lastP = parseFloat(flow.get("arec_last_p")) || 0;

// For Today's Energy via Riemann Sum
let energyToday = parseFloat(flow.get("arec_energy_today")) || 0.0;
let lastTime = flow.get("arec_last_time") || Date.now();
let lastDay = flow.get("arec_last_day") || new Date().getDate();
let now = Date.now();
let currentDay = new Date(now).getDate();

// Midnight Reset Logic
if (currentDay !== lastDay) {
    energyToday = 0.0;
    lastDay = currentDay;
    flow.set("arec_last_day", lastDay);
}

if (dps) {
    if (dps["107"] !== undefined) lastV = dps["107"] / 10;
    if (dps["106"] !== undefined) lastC = dps["106"] / 1000;
    if (dps["105"] !== undefined) lastP = dps["105"] / 10;
}

// Riemann Sum Integration (W -> kW -> kWh)
let hours = (now - lastTime) / 3600000;
// Sanity check to prevent massive energy spikes if Node-RED was off for days
if (hours > 0 && hours < 1) { 
    energyToday += (lastP / 1000) * hours;
}

flow.set("arec_last_time", now);
flow.set("arec_last_v", lastV);
flow.set("arec_last_c", lastC);
flow.set("arec_last_p", lastP);
flow.set("arec_energy_today", energyToday);

let timestamp = new Date().toLocaleString('en-US', { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit', second: '2-digit' });
let uiData = { 
    name: "ACU", 
    titleColor: "#00e5ff", 
    voltage: lastV.toFixed(1), 
    current: lastC.toFixed(3), 
    power: lastP.toFixed(1), 
    energy: energyToday.toFixed(3), 
    status: isOnline ? "CONNECTED" : "DISCONNECTED", 
    statusColor: isOnline ? "#00e676" : "#ff1744", 
    time: timestamp 
};

// Output 1 goes to UI Template continuously. Output 2 goes to Chart ONLY when Tuya sends data (prevents chart spam)
return [ { payload: uiData }, isTick ? null : { payload: lastP } ];

const TOKEN = env.get('LIGHT_API_TOKEN');
if (!TOKEN || msg.req.headers['x-auth-token'] !== TOKEN) {
    msg.statusCode = 401;
    msg.payload = { ok:false, error:'unauthorized' };
    return [null, msg];
}
// AC Master Logic looks the payload up in its IR code library, so anything outside that set
// resolves to no code and silently does nothing. Rejected here instead, where it can be seen.
const mode = String((msg.payload && msg.payload.mode) || '');
const ok = mode === 'OFF' || (/^\d{2}$/.test(mode) && Number(mode) >= 16 && Number(mode) <= 30);
if (!ok) {
    msg.statusCode = 400;
    msg.payload = { ok:false, error:'mode must be OFF or a whole degree 16-30' };
    return [null, msg];
}
msg.payload = mode;
delete msg.loop_prevention;
return [msg, null];

msg.statusCode = 200;
msg.payload = { ok: true };
return msg;

// Exponential back-off on failed discovery. See node-red-bridge/discoveryBackoffPlan.mjs.
//
// Driven by a status node scoped to this tab's tuya nodes. The vendor node reports
// fill 'green' when connected, 'red' when disconnected or errored, and 'yellow'
// while connecting — yellow is transitional and says nothing about the outcome, so
// counting it would make the schedule depend on an implementation detail.
const IDS_LIST = ["ae0a6d7639d18c4a","4d59cec67e18861f"];
const BASE = 1000;
const MAX = 60000;

// The reporting node is at msg.status.source, NOT msg.source — Node-RED's runtime builds it
// there (@node-red/runtime/lib/flows/Flow.js, handleStatus: "message.status.source = {id, type,
// name}"). Getting this wrong is SILENT: the id simply does not match, every output is null, and
// nothing is logged. It cost a live deploy that changed nothing on 2026-09-03. The fallback is
// belt-and-braces, not an alternative contract.
const st = (msg && msg.status) || {};
const src = st.source || (msg && msg.source) || {};
const idx = IDS_LIST.indexOf(src.id);
const out = IDS_LIST.map(function () { return null; });
if (idx < 0) return out;

const fill = st.fill;
if (fill !== 'green' && fill !== 'red') return out;

const store = context.get('backoff') || {};
const entry = store[src.id] || { fails: 0, applied: BASE };

let want;
if (fill === 'green') {
  entry.fails = 0;
  want = BASE;
} else {
  entry.fails = entry.fails + 1;
  want = BASE * Math.pow(2, entry.fails - 1);
  if (want > MAX) want = MAX;
}

// Only on change. Without this the cap would be re-sent every cycle forever, trading a loop of
// find attempts for a loop of control messages.
const changed = want !== entry.applied;
entry.applied = want;
store[src.id] = entry;
context.set('backoff', store);

if (!changed) return out;
out[idx] = { payload: { operation: 'CONTROL', action: 'SET_RETRY_TIMEOUT', value: want } };
return out;

// Force a fresh discovery when a node's find() has stopped broadcasting.
// See node-red-bridge/staleAddressPlan.mjs for the tuyapi short-circuit this works around.
//
// A find/connect cycle CANNOT complete faster than findTimeout unless find() short-circuited,
// so the yellow -> red latency is the detector. No error text is involved, because Node-RED
// carries none: the status text for a socket error is 'Error : {}'.
const IDS_LIST = ["ae0a6d7639d18c4a","4d59cec67e18861f"];
const LIMITS = [5000,5000];
const STREAK = 3;
const COOLDOWN = 60000;

// The reporting node is at msg.status.source — @node-red/runtime/lib/flows/Flow.js, handleStatus:
//   message.status.source = { id: node.id, type: node.type, name: node.name }
const st = (msg && msg.status) || {};
const src = st.source || (msg && msg.source) || {};
const idx = IDS_LIST.indexOf(src.id);
const out = IDS_LIST.map(function () { return null; });
if (idx < 0) return out;

const fill = st.fill;
if (fill !== 'green' && fill !== 'red' && fill !== 'yellow') return out;

const now = Date.now();
const store = flow.get("bems_stale_recovery") || {};
const entry = store[src.id] || { hits: 0, lastAt: null, yellowAt: null };

if (fill === 'yellow') {
  // findDevice() has just started. Only the FIRST yellow of a cycle matters: the vendor node
  // guards its state transitions, but a re-entered connecting must not restart the clock.
  if (entry.yellowAt === null) entry.yellowAt = now;
  store[src.id] = entry;
  flow.set("bems_stale_recovery", store);
  return out;
}

if (fill === 'green') {
  entry.hits = 0;
  entry.yellowAt = null;
  store[src.id] = entry;
  flow.set("bems_stale_recovery", store);
  return out;
}

// red: the cycle failed. How long it took is the whole signal.
const started = entry.yellowAt;
entry.yellowAt = null;
if (started === null) {
  // No cycle start seen — nothing can be concluded, so conclude nothing.
  store[src.id] = entry;
  flow.set("bems_stale_recovery", store);
  return out;
}

if ((now - started) >= LIMITS[idx]) {
  // A full-length cycle: find() really did broadcast. This is the state we are trying to
  // restore, so it clears the streak — which is what stops an absent device looping.
  entry.hits = 0;
  store[src.id] = entry;
  flow.set("bems_stale_recovery", store);
  return out;
}

entry.hits = entry.hits + 1;
// lastAt null means never recovered, which is not the same as recovered at the epoch — the
// cooldown must not block the FIRST recovery.
if (entry.hits < STREAK || (entry.lastAt !== null && (now - entry.lastAt) < COOLDOWN)) {
  store[src.id] = entry;
  flow.set("bems_stale_recovery", store);
  return out;
}

entry.hits = 0;
entry.lastAt = now;
store[src.id] = entry;
flow.set("bems_stale_recovery", store);

// DISCONNECT then CONNECT, in that order and on the one output. closeComm() clears the pending
// find timer; CONNECT's initTuya() then builds a NEW TuyaDevice, which is the whole point —
// tuyapi caches the resolved address on the instance, so only a new instance will broadcast.
out[idx] = [
  { payload: { operation: 'CONTROL', action: 'DISCONNECT' } },
  { payload: { operation: 'CONTROL', action: 'CONNECT' } }
];
return out;

// READ-ONLY. Reads this tab's flow context; writes nothing.
msg.snapshot = msg.snapshot || {};
msg.snapshot.aircon = { state: flow.get('ac_dash_state') || {} };
return msg;
